import { retryDelivery } from './delivery-service.mjs';

export class OrderService {
  constructor(users, send) { this.users = users; this.send = send; this.orders = new Map(); }

  createOrder(id, userId, lines) {
    if (this.orders.has(id)) throw new Error(`order ${id} already exists`);
    const order = { id, userId, lines, shipped: false };
    this.orders.set(id, order);
    return order;
  }

  getOrder(id) {
    const order = this.orders.get(id);
    if (!order) throw new Error(`order ${id} not found`);
    return order;
  }

  /** Totals the invoice lines of an order. */
  invoiceTotal(order) {
    return order.lines.filter(line => line.kind === 'invoice').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the shipment lines of an order. */
  shipmentTotal(order) {
    return order.lines.filter(line => line.kind === 'shipment').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the refund lines of an order. */
  refundTotal(order) {
    return order.lines.filter(line => line.kind === 'refund').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the subscription lines of an order. */
  subscriptionTotal(order) {
    return order.lines.filter(line => line.kind === 'subscription').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the coupon lines of an order. */
  couponTotal(order) {
    return order.lines.filter(line => line.kind === 'coupon').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the address lines of an order. */
  addressTotal(order) {
    return order.lines.filter(line => line.kind === 'address').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the warehouse lines of an order. */
  warehouseTotal(order) {
    return order.lines.filter(line => line.kind === 'warehouse').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the carrier lines of an order. */
  carrierTotal(order) {
    return order.lines.filter(line => line.kind === 'carrier').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the parcel lines of an order. */
  parcelTotal(order) {
    return order.lines.filter(line => line.kind === 'parcel').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the label lines of an order. */
  labelTotal(order) {
    return order.lines.filter(line => line.kind === 'label').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the customs lines of an order. */
  customsTotal(order) {
    return order.lines.filter(line => line.kind === 'customs').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the pickup lines of an order. */
  pickupTotal(order) {
    return order.lines.filter(line => line.kind === 'pickup').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the return lines of an order. */
  returnTotal(order) {
    return order.lines.filter(line => line.kind === 'return').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the notification lines of an order. */
  notificationTotal(order) {
    return order.lines.filter(line => line.kind === 'notification').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the webhook lines of an order. */
  webhookTotal(order) {
    return order.lines.filter(line => line.kind === 'webhook').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the audit lines of an order. */
  auditTotal(order) {
    return order.lines.filter(line => line.kind === 'audit').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the ledger lines of an order. */
  ledgerTotal(order) {
    return order.lines.filter(line => line.kind === 'ledger').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Totals the payout lines of an order. */
  payoutTotal(order) {
    return order.lines.filter(line => line.kind === 'payout').reduce((sum, line) => sum + line.price * line.quantity, 0);
  }

  /** Ships an order, but only for an active user. */
  async submitOrder(id) {
    const order = this.getOrder(id);
    if (!this.users.isActive(order.userId)) throw new Error('inactive user');
    await retryDelivery(order, this.send);
    order.shipped = true;
    return order;
  }
}

